shots.draw_js:
clearScene();setBig(null);
setEq("$$\\mathrm{MSE}(\\hat\\theta)\\;=\\;\\mathbb{E}\\big[(\\hat\\theta-\\theta)^2\\big]$$","top");
lamps({y:320,gap:340,items:[
  {label:"偏差",sub:"系统性偏到一边",state:"dead"},
  {label:"方差",sub:"每次都抖",state:"dead"}]});
setCap("要比较三个算法先得有一把尺子。而<b>这两样东西怎么合成一个数</b>，讲座说错了一个字。");

clearScene();setEq(null);
setBig("MSE = 偏差 + 方差","所以无偏估计总是更好的");
setCap("第一句<b>少了一个平方</b>；第二句由它顺理成章推出。两句合起来<b>刚好挡住 TD 为什么有用</b>。");

clearScene();setBig(null);
setEq("$$\\mathrm{MSE}\\;=\\;\\mathrm{Var}(\\hat\\theta)\\;+\\;\\mathrm{Bias}(\\hat\\theta)^2$$","top");
note("平方保证两项都 ≥ 0",640,320,"g lg");
note("没它，MSE 能算出负数",640,376,"r lg");
setCap("正确写法：<b>MSE = 方差 + 偏差²</b>。而 MSE 是平方的期望，<b>永远不可能为负</b>。");

clearScene();setBig(null);
setEq("$$X\\sim\\mathcal{N}(10,\\,1),\\qquad \\hat\\theta_1=X,\\quad \\hat\\theta_2=0.9X$$","top");
fillBars({vals:[0.808,0.994,1.802],order:[0,1,2],step:620,
  x:330,y:430,w:620,h:170,max:2,
  label:function(i){return ["方差","偏差²","实测 MSE"][i];},
  cls:function(i){return i===2?"g":"v";},
  fmt:function(v){return v.toFixed(3);}});
setCap("20 万次抽样：<b>0.808 + 0.994 = 1.802</b>，与直接测出的 MSE 逐位吻合。");

clearScene();setBig(null);
setEq("$$X\\sim\\mathcal{N}(1,\\,9):\\qquad \\hat\\theta=X \\;\\text{（无偏）}\\quad\\text{vs}\\quad \\hat\\theta=0.1X$$","top");
fillBars({vals:[9.00,0.90],order:[0,1],step:800,
  x:330,y:430,w:620,h:170,max:9.5,
  label:function(i){return ["无偏 X","有偏 0.1X"][i];},
  cls:function(i){return i===0?"r":"g";},
  fmt:function(v){return v.toFixed(2);}});
setCap("<b>有偏可以完胜无偏</b>：0.1X 的偏差高达 −0.9，MSE 却从 9.00 降到 0.90。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:300,items:[
  {label:"方差 + 偏差",sub:"0.808−0.997=−0.189",state:"dead"},
  {label:"方差 + 偏差²",sub:"0.808+0.994=1.802",state:"on"},
  {label:"无偏必更好",sub:"反例 9.00 vs 0.90",state:"dead"}]});
setCap("<b>指名反驳</b>：判据是<b>总 MSE</b>。无偏只在方差相同时才更好 —— 而这正是 TD 存在的理由。");

clearScene();setBig(null);setEq(null);
mdpChain({n:4,y:280,r:28,x:400,gap:160,
  label:function(i){return ["s₃","s₂","s₂","s₁"][i];},
  cls:function(i){return (i===1||i===2)?"v":"";},
  rew:function(i){return i===3?"+1":"0";},
  arcs:[[0,1,"","",0],[1,2,"","",0],[2,3,"","",0]]});
note("s₂ 出现了两次",640,400,"v");
setCap("同一回合里重复访问：<b>两次都算，还是只算第一次？</b>这个选择决定了估计有没有偏。");

clearScene();setEq(null);
setBig("当然两次都算","样本越多，估计越准");
setCap("「样本越多越准」少说了两个字：<b>独立</b>样本越多越准。");

clearScene();setBig(null);
setEq("$$G^{(1)}=r_2+\\gamma r_3+\\gamma^2 r_4,\\qquad G^{(2)}=r_3+\\gamma r_4$$","top");
note("共享 r₃ 与 r₄",640,330,"v lg");
note("共享 ⟹ 相关 ⟹ 有偏",640,390,"r lg");
setCap("后半段运气好，两个样本会<b>同时</b>偏高 —— 误差不抵消，反而叠加。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"首次访问",sub:"无偏 · 方差相同",state:"on"},
  {label:"每次访问",sub:"有偏 · 方差相同",state:"dead"}]});
note("同计数下首次访问占优",640,420,"g");
setCap("一样的方差，却没有偏差。<b>每次访问的全部优势是计数攒得快</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:260,items:[
  {label:"首次访问",sub:"无偏 · 相合",state:"on"},
  {label:"每次访问",sub:"有偏 · 相合",state:"on"},
  {label:"同计数比",sub:"首次占优",state:"on"},
  {label:"实际用量",sub:"每次攒得快",state:"on"}]});
setCap("<b>指名反驳</b>：多的是样本量，不是信息量。两者<b>都相合</b>，差别只在有限样本。");

clearScene();setBig(null);
setEq("$$V(s)\\;\\leftarrow\\;V(s)+\\alpha\\big[\\,G_t-V(s)\\,\\big],\\qquad \\alpha=\\tfrac{1}{N(s)}$$","top");
note("这就等于求算术平均",640,330,"g lg");
note("但 N 数的是什么？",640,390,"r lg");
setCap("增量式 + α = 1/N(s) = 求平均。<b>而「哪个 N」讲座没说</b>。");

clearScene();setEq(null);
setBig("增量式 = 每次访问","选了写法就等于选了计数规则");
setCap("这句话把<b>两个互相独立的选择</b>绑成了一个。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"开关一",sub:"批量 / 增量",state:"on"},
  {label:"开关二",sub:"首次 / 每次计数",state:"on"}]});
note("α=1/N 只管步长",640,420,"y");
setCap("α = 1/N(s) 说的是「步长跟着计数走」，<b>没说 N 数的是什么</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"首次计数",sub:"无偏",state:"on"},
  {label:"每次计数",sub:"有偏",state:"dead"}]});
note("批量/增量不改变它",640,420,"y");
setCap("「增量还是批量」是<b>工程</b>选择；「首次还是每次」才是<b>统计</b>选择。");

clearScene();setBig(null);setEq(null);
lamps({y:290,gap:340,items:[
  {label:"α = 1/N(s)",sub:"等权平均全部历史",state:"on"},
  {label:"α = 常数",sub:"按 (1−α)^k 遗忘",state:"on"}]});
note("常数 α 不收敛到算术平均",640,420,"y");
setCap("<b>指名反驳</b>：步长与计数规则是两个独立选择。常数 α 是<b>为非平稳环境准备的</b>。");
